def seed_organs(db: Session) -> None:
    existing_ids = {o.id for o in db.query(Organ.id).all()}
    added = 0
    for data in ORGANS:
        if data["id"] in existing_ids:
            continue
        sources = data.pop("sources", [])
        organ = Organ(**data)
        db.add(organ)
        db.flush()
        for i, src in enumerate(sources):
            db.add(OrganSource(organ_id=organ.id, position=i, **src))
        added += 1
    if added:
        db.commit()
